From 72d831edeb1c8ebb208b926e152c854656fc567a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:53:05 +0100
Subject: [PATCH] containments/desktop: Continue rubber band selection across
 screens

Each screen's desktop has its own Folder View, so a rubber band started
on one screen stopped at its edge and couldn't select icons on the next
one. The band is now shared, so the other screens draw and select too.

BUG: 455164
---
 .../package/contents/ui/FolderView.qml        | 60 ++++++++++++++++++-
 .../desktop/plugins/folder/foldermodel.cpp    | 10 ++++
 .../desktop/plugins/folder/foldermodel.h      |  3 +
 3 files changed, 72 insertions(+), 1 deletion(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..a4f457f39b 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -24,6 +24,8 @@ FocusScope {

     property Folder.FolderModel model: dir
     property Item rubberBand: null
+    // The part of a rubber band started on another screen's desktop that reaches this one
+    property Item sharedRubberBand: null

     property alias view: gridView
     property alias isRootView: gridView.isRootView
@@ -476,6 +478,14 @@ FocusScope {

                 Qt.callLater(gridView.rectangleSelect, rB.x, rB.y, rB.width, rB.height, main.rubberBand);

+                if (dir.usedByContainment) {
+                    const screen = Plasmoid.containment.screenGeometry;
+                    const sPress = mapToItem(null, pressX, pressY);
+                    const sPos = mapToItem(null, mouse.x, mouse.y);
+                    dir.shareRubberBand(Qt.rect(screen.x + Math.min(sPress.x, sPos.x), screen.y + Math.min(sPress.y, sPos.y),
+                        Math.max(1, Math.abs(sPos.x - sPress.x)), Math.max(1, Math.abs(sPos.y - sPress.y))), gridView.ctrlPressed);
+                }
+
                 return;
             }

@@ -582,6 +592,10 @@ FocusScope {
                 gridView.interactive = true;
                 gridView.cachedRectangleSelection = null;
                 dir.unpinSelection();
+
+                if (dir.usedByContainment) {
+                    dir.shareRubberBand(Qt.rect(0, 0, 0, 0), false);
+                }
             }

             clearPressState();
@@ -905,6 +919,10 @@ FocusScope {
                 }

                 function rectangleSelect(x, y, width, height, rubberBand) {
+                    gridView.cachedRectangleSelection = rectangleIndices(rubberBand);
+                }
+
+                function rectangleIndices(rubberBand) {
                     const rows = (gridView.flow === GridView.FlowLeftToRight);
                     const stripes = Math.ceil(gridView.count / positioner.perStripe);
                     const cWidth = gridView.cellWidth - (2 * Kirigami.Units.smallSpacing);
@@ -942,7 +960,41 @@ FocusScope {
                         }
                     }

-                    gridView.cachedRectangleSelection = indices;
+                    return indices;
+                }
+
+                function sharedRectangleSelect(globalRect, toggle) {
+                    const screen = Plasmoid.containment.screenGeometry;
+                    const topLeft = contentItem.mapFromItem(null, globalRect.x - screen.x, globalRect.y - screen.y);
+                    const viewTopLeft = contentItem.mapFromItem(gridView, 0, 0);
+                    const x = Math.max(topLeft.x, viewTopLeft.x);
+                    const y = Math.max(topLeft.y, viewTopLeft.y);
+                    const width = Math.min(topLeft.x + globalRect.width, viewTopLeft.x + gridView.width) - x;
+                    const height = Math.min(topLeft.y + globalRect.height, viewTopLeft.y + gridView.height) - y;
+
+                    if (globalRect.width === 0 || width < 0 || height < 0 || !main.Window.window?.visible) {
+                        if (main.sharedRubberBand) {
+                            main.sharedRubberBand.close();
+                            main.sharedRubberBand = null;
+                            if (globalRect.width !== 0) {
+                                dir.updateSelection([], toggle);
+                            }
+                            dir.unpinSelection();
+                        }
+                        return;
+                    }
+
+                    if (!main.sharedRubberBand) {
+                        dir.pinSelection();
+                        main.sharedRubberBand = rubberBandObject.createObject(contentItem);
+                    }
+
+                    const rB = main.sharedRubberBand;
+                    rB.x = x;
+                    rB.y = y;
+                    rB.width = Math.max(1, width);
+                    rB.height = Math.max(1, height);
+                    dir.updateSelection(rectangleIndices(rB).map(row => positioner.map(row)), toggle);
                 }

                 function runOrCdSelected() {
@@ -1235,6 +1287,12 @@ FocusScope {

             onRequestRename: main.rename()

+            onSharedRubberBandChanged: (globalRect, toggle) => {
+                if (usedByContainment) {
+                    gridView.sharedRectangleSelect(globalRect, toggle);
+                }
+            }
+
             onPopupMenuAboutToShow: (dropJob, mimeData, x, y) => {
                 if (Plasmoid.isContainment && !Plasmoid.immutable) {
                     root.processMimeData(mimeData, x, y, dropJob);
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..ba0576d3a6 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -220,6 +220,11 @@ FolderModel::FolderModel(QObject *parent)
 {
     connect(DragTracker::self(), &DragTracker::dragInProgressChanged, this, &FolderModel::draggingChanged);
     connect(DragTracker::self(), &DragTracker::dragInProgressChanged, this, &FolderModel::dragInProgressAnywhereChanged);
+    connect(DragTracker::self(), &DragTracker::rubberBandChanged, this, [this](FolderModel *owner, const QRectF &globalRect, bool toggle) {
+        if (owner != this) {
+            Q_EMIT sharedRubberBandChanged(globalRect, toggle);
+        }
+    });
     DirLister *dirLister = new DirLister(this);
     dirLister->setDelayedMimeTypes(true);
     dirLister->setAutoErrorHandlingEnabled(false);
@@ -1118,6 +1123,11 @@ void FolderModel::unpinSelection()
     m_pinnedSelection = QItemSelection();
 }

+void FolderModel::shareRubberBand(const QRectF &globalRect, bool toggle)
+{
+    Q_EMIT DragTracker::self()->rubberBandChanged(this, globalRect, toggle);
+}
+
 void FolderModel::addItemDragImage(int row, int x, int y, int width, int height, const QVariant &image)
 {
     if (row < 0) {
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..29f45fa92e 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -243,6 +243,7 @@ public:
     Q_INVOKABLE void clearSelection();
     Q_INVOKABLE void pinSelection();
     Q_INVOKABLE void unpinSelection();
+    Q_INVOKABLE void shareRubberBand(const QRectF &globalRect, bool toggle);

     Q_INVOKABLE void addItemDragImage(int row, int x, int y, int width, int height, const QVariant &image);
     Q_INVOKABLE void clearDragImages();
@@ -322,6 +323,7 @@ Q_SIGNALS:
     void itemRenamed(const QString &filename, const QString &newFilename) const;
     void screenGeometryChanged() const;
     void selectionDone();
+    void sharedRubberBandChanged(const QRectF &globalRect, bool toggle);
     void creatingNewItemsChanged() const;
     void selectionCountChanged() const;
     void itemDeleted(const QUrl &url);
@@ -444,6 +446,7 @@ public:

 Q_SIGNALS:
     void dragInProgressChanged(bool dragInProgress);
+    void rubberBandChanged(FolderModel *owner, const QRectF &globalRect, bool toggle);

 private:
     bool m_dragInProgress = false;
